using System.Security.Claims;using HealthTracker.Api.Contracts;using HealthTracker.Api.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace HealthTracker.Api.Controllers;[Authorize][ApiController][Route("api/doses")]public class DosesController(IDoseService s):ControllerBase{Guid U=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);[HttpGet]public async Task<IActionResult>Get([FromQuery]DateOnly? date)=>Ok(await s.Get(U,date??DateOnly.FromDateTime(DateTime.UtcNow)));[HttpPost("{id:guid}/taken")]public async Task<IActionResult>Take(Guid id)=>Ok(await s.Take(U,id));[HttpPost("{id:guid}/skip")]public async Task<IActionResult>Skip(Guid id,ReasonRequest r)=>Ok(await s.Skip(U,id,r.Reason));[HttpPost("{id:guid}/reschedule")]public async Task<IActionResult>Reschedule(Guid id,RescheduleRequest r)=>Ok(await s.Reschedule(U,id,DateOnly.Parse(r.Date)));[HttpPost("{id:guid}/undo")]public async Task<IActionResult>Undo(Guid id)=>Ok(await s.Undo(U,id));}